import 'package:flutter/material.dart';import '../core/utils/formatters.dart';import '../data/repositories/expense_repository.dart';import '../models/expense_transaction.dart';
class AddTransactionScreen extends StatefulWidget{const AddTransactionScreen({super.key,this.initialType='expense',this.item,required this.onSaved});final String initialType;final ExpenseTransaction? item;final VoidCallback onSaved;@override State<AddTransactionScreen> createState()=>_AddTransactionScreenState();}
class _AddTransactionScreenState extends State<AddTransactionScreen>{final repo=ExpenseRepository();final title=TextEditingController(),amount=TextEditingController(),note=TextEditingController();String type='expense';DateTime date=DateTime.now();int? categoryId,accountId;List<Map<String,Object?>> categories=[],accounts=[];bool busy=true,saving=false;
 @override void initState(){super.initState();type=widget.item?.type??widget.initialType;date=widget.item?.date??DateTime.now();title.text=widget.item?.title??'';amount.text=widget.item==null?'':(widget.item!.amountMinor/100).toStringAsFixed(2);note.text=widget.item?.note??'';load();}
 Future<void> load()async{final c=await repo.categories(type:type),a=await repo.accounts();if(!mounted)return;setState((){categories=c;accounts=a;categoryId=widget.item?.categoryId??(c.isEmpty?null:c.first['id'] as int);accountId=widget.item?.accountId??(a.isEmpty?null:a.first['id'] as int);busy=false;});}
 Future<void> changeType(String v)async{setState(()=>busy=true);final c=await repo.categories(type:v);if(!mounted)return;setState((){type=v;categories=c;categoryId=c.isEmpty?null:c.first['id'] as int;busy=false;});}
 Future<void> save()async{final n=double.tryParse(amount.text.trim());if(title.text.trim().isEmpty||n==null||n<=0||categoryId==null||accountId==null){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Enter a title, valid amount, category and account.')));return;}setState(()=>saving=true);await repo.save(ExpenseTransaction(id:widget.item?.id,title:title.text.trim(),type:type,amountMinor:(n*100).round(),categoryId:categoryId!,accountId:accountId!,date:date,note:note.text.trim()));widget.onSaved();if(mounted)Navigator.pop(context);}
 @override void dispose(){title.dispose();amount.dispose();note.dispose();super.dispose();}
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:Text(widget.item==null?'New transaction':'Edit transaction')),body:busy?const Center(child:CircularProgressIndicator()):ListView(padding:const EdgeInsets.all(20),children:[
 SegmentedButton<String>(segments:const[ButtonSegment(value:'expense',label:Text('Expense')),ButtonSegment(value:'income',label:Text('Income'))],selected:{type},onSelectionChanged:(s)=>changeType(s.first)),const SizedBox(height:20),
 TextField(controller:amount,keyboardType:const TextInputType.numberWithOptions(decimal:true),style:const TextStyle(fontSize:28,fontWeight:FontWeight.w800),decoration:const InputDecoration(labelText:'Amount',prefixText:'₹ ')),const SizedBox(height:14),
 TextField(controller:title,decoration:const InputDecoration(labelText:'Description')),const SizedBox(height:14),
 DropdownButtonFormField<int>(value:categoryId,decoration:const InputDecoration(labelText:'Category'),items:categories.map((e)=>DropdownMenuItem(value:e['id'] as int,child:Text(e['name'] as String))).toList(),onChanged:(v)=>setState(()=>categoryId=v)),const SizedBox(height:14),
 DropdownButtonFormField<int>(value:accountId,decoration:const InputDecoration(labelText:'Account'),items:accounts.map((e)=>DropdownMenuItem(value:e['id'] as int,child:Text(e['name'] as String))).toList(),onChanged:(v)=>setState(()=>accountId=v)),const SizedBox(height:10),
 ListTile(contentPadding:EdgeInsets.zero,title:const Text('Date'),subtitle:Text(Fmt.date(date)),trailing:const Icon(Icons.calendar_month),onTap:()async{final v=await showDatePicker(context:context,initialDate:date,firstDate:DateTime(2000),lastDate:DateTime(2100));if(v!=null)setState(()=>date=v);}),
 TextField(controller:note,maxLines:2,decoration:const InputDecoration(labelText:'Note (optional)')),const SizedBox(height:24),ElevatedButton(onPressed:saving?null:save,child:const Text('Save transaction'))
 ]));}
}
